const config = window.APP_CONFIG || {};
const blankGoals = { calories: 2000, proteinGrams: 150, carbsGrams: 250, fatGrams: 70, waterMl: 2500, setupComplete:false, goalType:'Maintain', maintenanceCalories:2000, age:30, heightCm:175, weightKg:70, calculationSex:'Male', activityLevel:1.375 };
const starterExercises = [['Barbell Shrug','Traps','Barbell'],['Dumbbell Shrug','Traps','Dumbbell'],['Bench Press (Barbell)','Chest','Barbell'],['Bench Press (Dumbbell)','Chest','Dumbbell'],['Back Squat','Quads','Barbell'],['Romanian Deadlift','Hamstrings','Barbell'],['Lat Pulldown','Back','Cable'],['Overhead Press','Shoulders','Barbell'],['Biceps Curl','Biceps','Dumbbell'],['Triceps Pushdown','Triceps','Cable'],['Running','Activity','Activity'],['Jogging','Activity','Activity'],['Walking','Activity','Activity'],['Swimming','Activity','Activity'],['Cycling','Activity','Activity'],['Yoga','Activity','Activity'],['Hiking','Activity','Activity'],['Rowing','Activity','Activity'],['Pilates','Activity','Activity'],['Dance','Activity','Activity'],['Elliptical','Activity','Activity']];
let exerciseChoices = [...starterExercises];
const state = { session: readSession(), page:'home', busy:false, message:'', profile:null, needsOnboarding:false, onboardingStep:0, onboarding:{}, pendingRecommendedPlan:readPendingRecommendedPlan(), nutritionExpandedMeal:'', savedFoodsExpanded:false, routines:[], sessions:[], foods:[], nutrition:null, nutritionGoalDefaults:null, date:null, today:null, clans:[], notices:[], challenges:[], activeWorkout:readWorkout(), username:'', authMode:'signin',authEmail:'',passwordRecovery:false,exerciseDownloadBusy:false, coachRelationships:[], coachRespondingId:null, coachedAthlete:null, recovery:null, recoveryRows:[], workoutHistoryExpanded:false, homeWorkoutHistoryExpanded:false, personalRecordsExpanded:false, timeZone:localStorage.getItem('gbNutritionTimeZone')||Intl.DateTimeFormat().resolvedOptions().timeZone };
state.today = state.date = localDate();
function readSession(){try{return JSON.parse(localStorage.getItem('gbWebSession')||'null')}catch{return null}}
function pendingPlanKey(userId=readSession()?.user?.id){return userId?`gbPendingRecommendedPlan:${userId}`:null}
function readPendingRecommendedPlan(){try{const key=pendingPlanKey();const plan=key?JSON.parse(localStorage.getItem(key)||'null'):null;return Array.isArray(plan)&&plan.length?plan:null}catch{return null}}
function saveSession(s){state.session=s;if(s)localStorage.setItem('gbWebSession',JSON.stringify(s));else localStorage.removeItem('gbWebSession')}
function workoutStorageKey(userId=readSession()?.user?.id){return userId?`gbActiveWorkout:${userId}`:null}
function readWorkout(userId=readSession()?.user?.id){const key=workoutStorageKey(userId);if(!key)return null;try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function persistWorkout(){const key=workoutStorageKey(state.session?.user?.id);if(!key)return;if(state.activeWorkout)localStorage.setItem(key,JSON.stringify(state.activeWorkout));else localStorage.removeItem(key)}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:state.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone}).format(new Date())}
function uid(){return crypto.randomUUID()}
function loadExerciseCache(){try{const cached=JSON.parse(localStorage.getItem('gbExerciseCatalog')||'[]');if(Array.isArray(cached)&&cached.length)exerciseChoices=[...starterExercises,...cached]}catch{}}
function exerciseLabels(raw){const name=String(raw.name_en||'').trim();const source=`${raw.body_part||''} ${(raw.primary_muscles||[]).join(' ')} ${name}`.toLowerCase();const muscle=/trapezius|\btrap|shrug/.test(source)?'Traps':/chest|pector/.test(source)?'Chest':/shoulder|deltoid/.test(source)?'Shoulders':/biceps/.test(source)?'Biceps':/triceps/.test(source)?'Triceps':/forearm/.test(source)?'Forearms':/back|latissimus|rhomboid/.test(source)?'Back':/hamstring/.test(source)?'Hamstrings':/glute/.test(source)?'Glutes':/calf|soleus/.test(source)?'Calves':/abdominal|oblique|core/.test(source)?'Core':/quad|thigh|leg/.test(source)?'Legs':'Other';let equipment=String(raw.equipment||'').replaceAll('_',' ').trim();if(raw.is_bodyweight&&(!equipment||equipment==='other'))equipment='Bodyweight';equipment=equipment?equipment.replace(/\b\w/g,c=>c.toUpperCase()):'Other';return [name,muscle,equipment]}
async function downloadExerciseLibrary(){if(state.exerciseDownloadBusy)return;state.exerciseDownloadBusy=true;render();try{const response=await fetch('https://exercise-dataset.com/exercises.json',{mode:'cors',cache:'no-cache'});if(!response.ok)throw new Error(`Exercise catalog request failed (${response.status}).`);const json=await response.json(),rows=Array.isArray(json?.exercises)?json.exercises:[];const downloaded=[...new Map(rows.map(exerciseLabels).filter(x=>x[0]).map(x=>[x[0].toLowerCase(),x])).values()];if(downloaded.length<100)throw new Error('The exercise catalog was incomplete; try downloading again.');exerciseChoices=[...starterExercises,...downloaded.filter(x=>!starterExercises.some(s=>s[0].toLowerCase()===x[0].toLowerCase()))];localStorage.setItem('gbExerciseCatalog',JSON.stringify(exerciseChoices.slice(starterExercises.length)));flash('Exercise library updated. Search exercises while building a workout.')}catch(error){flash(error.message||'Could not download the exercise catalog.','error')}finally{state.exerciseDownloadBusy=false;render()}}
function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d}
function f(v,d=0){return new Intl.NumberFormat(undefined,{maximumFractionDigits:d}).format(n(v))}
function flash(m,k='info'){state.message=m;state.messageKind=k;render()}
function authUrl(p){return `${config.supabaseUrl.replace(/\/$/,'')}/auth/v1/${p}`}
function appCallbackUrl(){return new URL('./',location.href).toString()}
function apiUrl(p){return `${config.supabaseUrl.replace(/\/$/,'')}/rest/v1/${p}`}
function baseHeaders(){return {apikey:config.supabasePublishableKey,'Content-Type':'application/json'}}
function bearerHeaders(){if(!state.session?.access_token)throw new Error('Please sign in again.');return {...baseHeaders(),Authorization:`Bearer ${state.session.access_token}`}}
async function authRequest(path,body){const r=await fetch(authUrl(path),{method:'POST',headers:baseHeaders(),body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.msg||d.message||d.error_description||'Account request failed.');return d}
async function refreshTokenIfNeeded(){if(!state.session?.refresh_token||n(state.session.expires_at)>Date.now()/1000+60)return;const d=await authRequest('token?grant_type=refresh_token',{refresh_token:state.session.refresh_token});saveSession({...d,expires_at:Math.floor(Date.now()/1000)+n(d.expires_in,3600)})}
async function db(path,{method='GET',body,prefer='',query=''}={}){await refreshTokenIfNeeded();const h=bearerHeaders();if(prefer)h.Prefer=prefer;const r=await fetch(`${apiUrl(path)}${query?`?${query}`:''}`,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});const raw=await r.text();const d=raw?JSON.parse(raw):null;if(!r.ok)throw new Error(d?.message||d?.hint||d?.details||'Could not sync account data.');return d}
function rpc(name,args={}){return db(`rpc/${encodeURIComponent(name)}`,{method:'POST',body:args})}
function recoverAuthCallback(hash){const h=new URLSearchParams(String(hash||'').replace(/^#/,'').replace(/^\?/,'').replace(/^.*#/,''));return{accessToken:h.get('access_token'),refreshToken:h.get('refresh_token'),expiresAt:n(h.get('expires_at'),Date.now()/1000+3600),type:h.get('type')||''}}
function absorbAuthCallback(){const callback=recoverAuthCallback(location.hash||location.search);if(callback.accessToken){const token=callback.accessToken;let user=state.session?.user;try{const part=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');const claims=JSON.parse(atob(part));user={id:claims.sub,email:claims.email}}catch{}saveSession({access_token:token,refresh_token:callback.refreshToken,expires_at:callback.expiresAt,user});state.passwordRecovery=callback.type==='recovery';history.replaceState({},'',location.pathname+location.search)}}
function handleError(e){console.error(e);state.busy=false;flash(e?.message||'Something went wrong. Try again.','error')}
const nutritionMeals=['Breakfast','Lunch','Dinner','Snacks','Other'];
function currentNutritionMeal(){let hour;try{hour=Number(new Intl.DateTimeFormat('en',{timeZone:state.timeZone,hour:'numeric',hourCycle:'h23'}).format(new Date()))}catch{hour=new Date().getHours()}return hour>=5&&hour<11?'Breakfast':hour>=11&&hour<16?'Lunch':hour>=16&&hour<21?'Dinner':'Snacks'}
function normalizeNutrition(row){const foods=Array.isArray(row?.foods)?row.foods.map(food=>({...food,meal:nutritionMeals.includes(food.meal)?food.meal:'Other'})):[],goals={...blankGoals,...(state.nutritionGoalDefaults||{}),...(row?.goals||{})};goals.goalType=goals.goalType==='Lose'?'Fat loss':goals.goalType==='Gain'?'Muscle gain':['Fat loss','Recomp','Maintain','Muscle gain'].includes(goals.goalType)?goals.goalType:'Maintain';return row?{...row,foods,goals}:{user_id:state.session.user.id,date:state.date,water_ml:0,foods,goals}}
async function refreshData(){if(!state.session?.access_token)return render();state.activeWorkout=readWorkout(state.session.user.id);state.busy=true;render();try{await refreshTokenIfNeeded();const id=encodeURIComponent(state.session.user.id),requestedDate=state.date,priorToday=state.today;const [p,r,s,foods,nut,latestNutrition,notices,clans,coachRelationships,recoveryRows]=await Promise.all([db('profiles',{query:`select=*&id=eq.${id}&limit=1`}),db('routines',{query:`select=*&user_id=eq.${id}&order=updated_at.desc`}),db('workout_sessions',{query:`select=*&user_id=eq.${id}&order=started_at.desc`}),db('user_foods',{query:`select=*&user_id=eq.${id}&order=name.asc`}),db('daily_nutrition',{query:`select=*&user_id=eq.${id}&date=eq.${requestedDate}&limit=1`}),db('daily_nutrition',{query:`select=goals&user_id=eq.${id}&order=date.desc&limit=1`}),db('clan_notifications',{query:`select=*&user_id=eq.${id}&order=created_at.desc&limit=25`}).catch(()=>[]),rpc('my_clans').catch(()=>[]),rpc('my_coach_relationships').catch(()=>[]),db('recovery_daily',{query:`select=*&user_id=eq.${id}&order=date.desc&limit=90`}).catch(()=>[])]);state.profile=p?.[0]||null;state.needsOnboarding=!state.profile?.onboarding_data?.ageYears||!state.profile?.onboarding_data?.primaryGoal||!Array.isArray(state.profile?.onboarding_data?.availableEquipment);if(state.needsOnboarding){state.onboardingStep=0;state.onboarding={...(state.profile?.onboarding_data||{}),email:state.session.user.email||''}}const savedZone=state.profile?.onboarding_data?.timeZone;if(savedZone){try{new Intl.DateTimeFormat('en',{timeZone:savedZone});state.timeZone=savedZone;localStorage.setItem('gbNutritionTimeZone',savedZone)}catch{}}state.today=localDate();if(requestedDate===priorToday||!requestedDate)state.date=state.today;const finalNutrition=state.date===requestedDate?nut:await db('daily_nutrition',{query:`select=*&user_id=eq.${id}&date=eq.${state.date}&limit=1`});if(state.profile&&state.username)state.profile={...state.profile,username:state.username};state.routines=(r||[]).map(x=>({...x,definition:x.definition||{}}));state.sessions=s||[];state.foods=(foods||[]).map(x=>({id:x.id,name:x.name,brand:x.brand||'',servingGrams:n(x.serving_grams,100),servingAmount:n(x.serving_amount,n(x.serving_grams,100)),servingUnit:x.serving_unit||'g',calories:Math.round(n(x.calories_per_serving,n(x.calories_per_100g)*n(x.serving_grams,100)/100)),proteinGrams:n(x.protein_per_serving,n(x.protein_per_100g)*n(x.serving_grams,100)/100),carbsGrams:n(x.carbs_per_serving,n(x.carbs_per_100g)*n(x.serving_grams,100)/100),fatGrams:n(x.fat_per_serving,n(x.fat_per_100g)*n(x.serving_grams,100)/100)}));state.nutritionGoalDefaults=latestNutrition?.[0]?.goals||null;state.nutrition=normalizeNutrition(finalNutrition?.[0]);state.notices=notices||[];state.clans=clans||[];state.coachRelationships=coachRelationships||[];state.recoveryRows=recoveryRows||[];state.recovery=state.recoveryRows[0]||null;state.busy=false;state.message='';render();if(state.page==='community'&&!state.needsOnboarding)await loadChallenges()}catch(e){state.busy=false;throw e}}
const refreshDataWithoutWorkoutHeartRate = refreshData;
refreshData = async function refreshDataWithWorkoutHeartRate(){await refreshDataWithoutWorkoutHeartRate();if(!state.session?.user?.id||!state.sessions.length)return;const ids=[...new Set(state.sessions.slice(0,30).map(s=>String(s.id)).filter(id=>/^[0-9a-f-]{36}$/i.test(id)))];if(!ids.length)return;const rows=await db('heart_rate_samples',{query:`select=workout_session_id,bpm,measured_at,source,device_label&user_id=eq.${encodeURIComponent(state.session.user.id)}&workout_session_id=in.(${ids.join(',')})&order=measured_at.asc&limit=3000`}).catch(()=>[]);const grouped=new Map();for(const row of rows||[]){const bpm=n(row.bpm);if(bpm<30||bpm>240||!ids.includes(String(row.workout_session_id)))continue;const list=grouped.get(row.workout_session_id)||[];list.push({bpm,measuredAt:row.measured_at,source:row.source,deviceLabel:row.device_label});grouped.set(row.workout_session_id,list)}state.sessions=state.sessions.map(session=>({...session,heartRateSamples:grouped.get(session.id)||[]}));render()};
function heartRateSummary(samples){const values=(samples||[]).map(x=>n(x.bpm)).filter(x=>x>=30&&x<=240);return values.length?{average:Math.round(values.reduce((a,b)=>a+b,0)/values.length),peak:Math.max(...values),count:values.length}:null}
function bodyweightLoadFraction(exerciseName,equipment){const name=String(exerciseName||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' '),eq=String(equipment||'').toLowerCase().trim();if(['barbell','dumbbell','kettlebell','cable','machine','smith','weighted'].some(x=>eq.includes(x)||name.startsWith(`${x} `)))return null;let fraction;if(name.includes('single leg glute bridge'))fraction=.75;else if(name.includes('glute bridge'))fraction=.55;else if(name.includes('incline push up'))fraction=.45;else if(name.includes('decline push up'))fraction=.75;else if(name.includes('push up')||name.includes('shoulder tap'))fraction=.65;else if(name.includes('pull up')||name.includes('chin up'))fraction=1;else if(name.includes('dip'))fraction=.85;else if(name.includes('inverted row')||name.includes('towel row'))fraction=.60;else if(name.includes('squat')||name.includes('lunge')||name.includes('split squat')||name.includes('nordic curl'))fraction=.90;else if(name.includes('calf raise'))fraction=.85;else if(name.includes('leg raise')||name.includes('flutter kick'))fraction=.50;else if(name.includes('crunch')||name.includes('russian twist')||name.includes('dead bug')||name.includes('bird dog'))fraction=.35;else fraction=.50;const hasBodyweightEquipment=eq.includes('bodyweight')||['none','no equipment','no-equipment','body only','body only / no equipment'].includes(eq),knownMovement=['glute bridge','push up','shoulder tap','pull up','chin up','dip','inverted row','towel row','squat','lunge','split squat','nordic curl','calf raise','leg raise','flutter kick','crunch','russian twist','dead bug','bird dog','plank','burpee','mountain climber','jumping jack'].some(x=>name.includes(x));return hasBodyweightEquipment||knownMovement?fraction:null}
function profileBodyWeightKg(profile=state.profile){const value=n(profile?.weight_value,NaN);if(!Number.isFinite(value)||value<=0)return 0;const kg=String(profile?.weight_unit||'kg').toLowerCase().startsWith('lb')?value/2.2046226218:value;return Number.isFinite(kg)&&kg>=30&&kg<=350?kg:0}
function effectiveBodyweightLoadKg(exercise,profile=state.profile){const fraction=bodyweightLoadFraction(exercise?.exercise?.name,exercise?.exercise?.equipment);return fraction==null?null:profileBodyWeightKg(profile)*fraction}
async function persistNutrition(next){next.updated_at=new Date().toISOString();state.nutrition=next;render();await db('daily_nutrition?on_conflict=user_id,date',{method:'POST',body:next,prefer:'resolution=merge-duplicates,return=minimal'})}
async function signIn(email,password,create=false){state.busy=true;render();try{const d=await authRequest(create?`signup?redirect_to=${encodeURIComponent(appCallbackUrl())}`:`token?grant_type=password`,{email,password});if(d.access_token){saveSession({...d,expires_at:Math.floor(Date.now()/1000)+n(d.expires_in,3600)});state.page='home';await refreshData()}else if(create&&d.user){state.busy=false;state.authMode='signin';state.authEmail=email;flash('Account created. Check your email to confirm it, then sign in here.')}else{state.busy=false;flash(create?'The account could not be created. Please try again.':'Sign-in did not return a session. Check your details and try again.','error')}}catch(e){state.busy=false;flash(e.message,'error')}}
async function signOut(){try{await fetch(authUrl('logout'),{method:'POST',headers:{...baseHeaders(),Authorization:`Bearer ${state.session?.access_token||''}`}})}catch{}saveSession(null);state.profile=null;state.pendingRecommendedPlan=null;state.routines=[];state.sessions=[];state.foods=[];state.nutrition=null;state.activeWorkout=null;state.page='home';render()}

loadExerciseCache();
if(!config.supabaseUrl||!config.supabasePublishableKey){root.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><h1>Build strength.<br><em>One rep at a time.</em></h1><p>Connect to the existing Anvil Quest Supabase project to use the same account and training data as Android.</p></section><section class="auth-card"><h2>Connection unavailable</h2><p class="muted">The browser could not load the public app configuration. Check your connection and try again.</p><p class="muted small">Only a publishable key belongs in browser code. Never use a service-role or secret key here.</p></section></main>`}else{absorbAuthCallback();render();if(state.session?.access_token&&!state.passwordRecovery)refreshData().catch(handleError)}

function navIcon(id){const common='fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"';const paths={home:'<path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9M9 20v-6h6v6"/>',workouts:'<path d="M6 6v12M3 9v6M18 6v12M21 9v6M6 12h12"/>',nutrition:'<path d="M4 3v7M7 3v7M4 7h3M5.5 10v11M15 3v8a3 3 0 0 0 3 0V3M16.5 3v18"/>',progress:'<path d="M3 3v18h18"/><path d="m6 15 4-4 3 2 5-7"/><path d="M16 6h2v2"/>',avatar:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',community:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="M9 12h6M12 9v6"/>',profile:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',signout:'<path d="M10 17l5-5-5-5M15 12H3"/><path d="M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" ${common}>${paths[id]||paths.profile}</svg>`}
function render(){if(state.passwordRecovery){renderPasswordRecovery();return}if(!state.session?.access_token){renderAuth();return}if(state.needsOnboarding){renderOnboarding();return}if(state.pendingRecommendedPlan&&state.page!=='workouts'){renderPlanReview();return}const pages={home:renderHome,workouts:renderWorkouts,nutrition:renderNutrition,community:renderCommunity,profile:renderProfile,about:renderAbout,progress:renderProgress,xp:renderXpJourney,avatar:renderAvatar,activity:renderActivity};const nav=[['home','ANVIL'],['workouts','QUEST'],['nutrition','NUTRITION'],['progress','PROGRESS'],['avatar','AVATAR'],['community','COMMUNITY']];const currentSection=nav.find(([id])=>id===state.page)?.[1]||({xp:'XP JOURNEY',activity:'ACTIVITY',profile:'SETTINGS'}[state.page]||String(state.page).toUpperCase());root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><nav class="nav">${nav.map(([id,name])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${navIcon(id)}</span>${name}</button>`).join('')}</nav><div class="side-bottom">FORGE YOUR OWN PATH<br><span class="gold">${esc(state.profile?.training_path||'BUILDER')}</span><br><br><button class="button" data-action="refresh">SYNC ACCOUNT</button></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><details class="account-menu"><summary aria-label="Open account menu" title="Menu">${navIcon('menu')}</summary><div class="account-menu-panel"><div class="account-menu-label">ACCOUNT</div><button data-nav="profile">${navIcon('profile')}SETTINGS</button><button data-action="signout">${navIcon('signout')}SIGN OUT</button></div></details><div class="eyebrow"><span>THE GODBUILDER</span><b aria-hidden="true">›</b><span>${esc(currentSection)}</span></div></div><div class="row"><span class="user-chip">${esc(state.profile?.username?`@${state.profile.username}`:state.session.user.email||'WARRIOR')}</span></div></header><div class="content">${state.message?`<div class="notice" role="status">${esc(state.message)}</div><div style="height:14px"></div>`:''}${state.busy?`<div class="notice">Syncing securely with your account…</div>`:''}${(pages[state.page]||renderHome)()}</div></main><nav class="mobile-nav">${nav.map(([id,name])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${navIcon(id)}</span>${name}</button>`).join('')}</nav></div>`;if(state.page==='progress')requestAnimationFrame(renderMuscleMap);if(state.page==='avatar')requestAnimationFrame(renderAvatarMorphCanvases)}
function renderAuth(){const reset=state.authMode==='reset-email',signup=state.authMode==='signup';root.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><div><div class="kicker">TRAIN • EAT • RECOVER</div><h1>Build strength.<br><em>One rep at a time.</em></h1><p>Your training log, saved workouts and nutrition travel with your account across Android and web.</p></div><div class="muted small">THE ANVIL QUEST · FORGE YOUR OWN PATH</div></section><section class="auth-card"><div class="mobile-only kicker">THE GODBUILDER</div><h2>${reset?'Reset your password':signup?'Create your account':'Welcome back'}</h2><p class="muted small">${reset?'Enter your account email. We’ll send a secure link to choose a new password.':'Use the same email and password as the Android app.'}</p><form id="auth-form"><div class="field"><label>Email</label><input class="input" type="email" name="email" value="${esc(state.authEmail||'')}" autocomplete="email" required></div>${reset?'':`<div class="field"><label>Password</label><input class="input" type="password" name="password" minlength="6" autocomplete="${signup?'new-password':'current-password'}" required></div>`}${signup?`<label class="small muted"><input type="checkbox" name="marketing"> Send me optional product news</label>`:''}<div class="message" role="status">${esc(state.message)}</div><button class="button primary" ${state.busy?'disabled':''}>${state.busy?'PLEASE WAIT…':reset?'SEND RESET LINK':signup?'CREATE ACCOUNT':'SIGN IN'}</button></form><div class="row between" style="margin-top:12px"><button class="button" data-action="toggle-auth">${signup?'Already have an account?':reset?'Back to sign in':'Create account'}</button>${!reset&&!signup?`<button class="button" data-action="reset-password">Forgot password?</button>`:''}</div></section></main>`}
function renderPasswordRecovery(){root.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><div><div class="kicker">ACCOUNT SECURITY</div><h1>Set a new<br><em>password.</em></h1><p>Choose a new password for your GodBuilder account.</p></div><div class="muted small">THE ANVIL QUEST</div></section><section class="auth-card"><h2>Choose a new password</h2><p class="muted small">Use at least 8 characters. You’ll sign in again after it is saved.</p><form id="password-recovery-form"><div class="field"><label>New password</label><input class="input" type="password" name="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>Confirm new password</label><input class="input" type="password" name="confirmPassword" minlength="8" autocomplete="new-password" required></div><div class="message" role="status">${esc(state.message)}</div><button class="button primary" ${state.busy?'disabled':''}>${state.busy?'SAVING…':'SAVE NEW PASSWORD'}</button></form></section></main>`}
async function requestPasswordReset(email){state.busy=true;render();try{await authRequest(`recover?redirect_to=${encodeURIComponent(appCallbackUrl())}`,{email});state.busy=false;state.authMode='signin';state.authEmail=email;flash('If this email belongs to an account, a recovery link has been sent. Check your inbox and spam folder.')}catch(error){state.busy=false;const detail=String(error?.message||'');flash(/rate.?limit|too many requests/i.test(detail)?'Password reset email limit reached. Wait before requesting another email. If you already received a recovery link, open it to set a new password.':detail,'error')}}
async function completePasswordReset(password,confirmPassword){if(password.length<8)throw new Error('Use at least 8 characters for your new password.');if(password!==confirmPassword)throw new Error('The passwords do not match.');state.busy=true;render();try{const response=await fetch(`${config.supabaseUrl.replace(/\/$/,'')}/auth/v1/user`,{method:'PUT',headers:{...baseHeaders(),Authorization:`Bearer ${state.session?.access_token||''}`},body:JSON.stringify({password})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.msg||result.message||result.error_description||'Could not update the password. Request a fresh recovery link and try again.');const email=state.session?.user?.email||'';saveSession(null);state.passwordRecovery=false;state.authMode='signin';state.authEmail=email;state.busy=false;flash('Password updated. Sign in with your new password.')}catch(error){state.busy=false;flash(error.message||'Could not update the password.','error')}}
function head(k,t,d,a=''){return `<div class="page-head"><div><div class="kicker">${t==='Welcome'?'YOUR FORGE':k}</div><h1>${t}</h1><p>${d}</p></div>${a}</div>`}
function card(title,content){return `<section class="card"><h2>${title}</h2>${content}</section>`}
function localSessionDate(s){return new Date(s.started_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function localDay(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:state.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone}).format(date)}
function weekKey(date=new Date()){const parts=localDay(date).split('-').map(Number),d=new Date(Date.UTC(parts[0],parts[1]-1,parts[2]));d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
function avatarPresentation(profile={}){const value=String(profile?.gender||profile?.onboarding_data?.gender||'Male').trim().toLowerCase();return value==='female'||value==='woman'||value==='f'||value.includes('fem')?'female':'male'}
function targetPerWeek(){return Math.min(7,Math.max(1,n(state.profile?.onboarding_data?.sessionsPerWeek,3)))}
function completedSets(session){return (session.exercise_logs||[]).flatMap(e=>e.sets||[]).filter(s=>s.completed!==false&&String(s.set_type||s.setType||'WORKING').toUpperCase()==='WORKING')}
function xpLedger(sessions=state.sessions,target=targetPerWeek()){const ordered=[...sessions].filter(s=>completedSets(s).length).sort((a,b)=>new Date(a.started_at)-new Date(b.started_at)),best=new Map(),weekly=new Map(),days=new Map(),ledger=new Map();for(let i=0;i<ordered.length;i++){const s=ordered[i],sets=completedSets(s),date=new Date(s.started_at),day=localDay(date);let xp=Math.min(sets.length*10,100)+40+(i===0?100:0),prs=0;for(const ex of s.exercise_logs||[]){const name=String(ex.exercise?.name||ex.exercise_name||ex.name||'').trim().toLowerCase();if(!name)continue;const est=(ex.sets||[]).filter(x=>x.completed!==false&&String(x.set_type||x.setType||'WORKING').toUpperCase()==='WORKING').map(estimated1rm).filter(x=>x>0);const top=Math.max(0,...est);if(top>(best.get(name)||0)){prs++;best.set(name,top)}}xp+=Math.min(prs*25,75);const wk=weekKey(date),count=(weekly.get(wk)||0)+1;weekly.set(wk,count);if(count===target)xp+=75;const used=days.get(day)||0,awarded=Math.max(0,Math.min(xp,250-used));days.set(day,used+awarded);ledger.set(s.id,awarded)}return ledger}
function xpForSessions(sessions=state.sessions,target=targetPerWeek()){return [...xpLedger(sessions,target).values()].reduce((a,b)=>a+b,0)}
function sessionStats(){const currentWeek=weekKey(new Date()),w=state.sessions.filter(s=>weekKey(new Date(s.started_at))===currentWeek);return{week:w.length,volume:w.reduce((a,s)=>a+n(s.total_volume_kg),0),total:state.sessions.length,streak:weeklyStreak()}}
function weeklyStreak(){const goal=targetPerWeek(),counts=new Map();for(const s of state.sessions){const k=weekKey(new Date(s.started_at));counts.set(k,(counts.get(k)||0)+1)}const d=new Date(`${weekKey(new Date())}T00:00:00Z`);if((counts.get(d.toISOString().slice(0,10))||0)<goal)d.setUTCDate(d.getUTCDate()-7);let streak=0;while((counts.get(d.toISOString().slice(0,10))||0)>=goal){streak++;d.setUTCDate(d.getUTCDate()-7)}return streak}
function renderRecoveryCard(){const r=state.recovery;if(!r)return `<div><p class="muted small">Connect Health Connect in Android and allow recovery and activity access to share your latest summary here.</p><button class="button" data-nav="activity">VIEW ACTIVITY HISTORY</button></div>`;const details=[r.sleep_minutes!=null?`Sleep ${Math.floor(r.sleep_minutes/60)}h ${r.sleep_minutes%60}m`:null,r.hrv_millis!=null?`HRV ${f(r.hrv_millis)} ms`:null,r.resting_heart_rate!=null?`Resting HR ${f(r.resting_heart_rate)} bpm`:null].filter(Boolean).join(' · ');const activity=[r.steps!=null?`${f(r.steps)} steps`:null,r.daily_distance_meters!=null?`${f(r.daily_distance_meters/1000,1)} km distance today`:null,r.weekly_runs!=null?`${f(r.weekly_runs)} runs`:null,r.weekly_run_distance_meters!=null?`${f(r.weekly_run_distance_meters/1000,1)} km running`:null].filter(Boolean).join(' · ');return `<div><div class="row between"><strong class="gold">${r.recovery_score==null?'ACTIVITY':`${f(r.recovery_score)} / 100`}</strong><small class="muted">${esc(r.date)} · Android sync</small></div>${r.recovery_score==null?'':`<div class="progress" style="margin:8px 0"><i style="width:${Math.max(0,Math.min(100,n(r.recovery_score)))}%"></i></div>`}<p class="small muted">${esc(details||'No sleep or recovery signals synced yet.')}</p><p class="small muted">${esc(activity||'Steps and running metrics are unavailable.')}</p><small class="muted">Estimate only; not a medical assessment.</small><div style="margin-top:10px"><button class="button" data-nav="activity">VIEW ACTIVITY HISTORY</button></div></div>`}
function renderActivity(){const rows=[...(state.recoveryRows||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date)));if(!rows.length)return `${head('ACTIVITY','Recovery & activity','Wearable summaries synced through Health Connect on Android.')}<div class="card"><p class="muted">No activity history has synced yet. On Android, allow Recovery Data access in Settings; Fitbit and other devices need to sync their readings to Health Connect first.</p><button class="button" data-action="refresh">CHECK FOR SYNCED DATA</button></div>`;const latest=rows[0],recent=rows.slice(0,14),maxSteps=Math.max(1,...recent.map(x=>n(x.steps))),weeklyRun=latest.weekly_runs==null&&latest.weekly_run_distance_meters==null?'<div class="empty">No running summary synced.</div>':`<div class="grid stats"><div class="card stat"><div class="label">RUNS · LAST 7 DAYS</div><div class="value">${latest.weekly_runs==null?'—':f(latest.weekly_runs)}</div></div><div class="card stat"><div class="label">RUN DISTANCE · LAST 7 DAYS</div><div class="value">${latest.weekly_run_distance_meters==null?'—':`${f(latest.weekly_run_distance_meters/1000,1)} km`}</div></div></div>`;const bars=recent.slice().reverse().map(x=>`<div class="activity-bar-row"><span>${esc(new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(`${x.date}T12:00:00`)))}</span><div class="activity-bar-track"><i style="width:${Math.max(n(x.steps)?2:0,n(x.steps)/maxSteps*100)}%"></i></div><b>${x.steps==null?'—':f(x.steps)}</b></div>`).join('');const list=rows.slice(0,30).map(x=>`<div class="list-row"><div><strong>${esc(x.date)}</strong><small>${x.sleep_minutes==null?'Sleep —':`Sleep ${Math.floor(x.sleep_minutes/60)}h ${x.sleep_minutes%60}m`} · ${x.hrv_millis==null?'HRV —':`HRV ${f(x.hrv_millis)} ms`} · ${x.resting_heart_rate==null?'Resting HR —':`Resting HR ${f(x.resting_heart_rate)} bpm`}</small></div><span class="pill">${x.steps==null?'—':`${f(x.steps)} steps`}${x.daily_distance_meters==null?'':` · ${f(x.daily_distance_meters/1000,1)} km`}</span></div>`).join('');return `${head('ACTIVITY','Recovery & activity','Daily steps, distance, sleep and HRV, with your latest synced running summary.')}<div class="grid stats"><div class="card stat"><div class="label">LATEST RECOVERY</div><div class="value">${latest.recovery_score==null?'—':`${f(latest.recovery_score)} / 100`}</div><small class="muted">${latest.recovery_score==null?'No score available':`Updated ${esc(latest.date)}`}</small></div><div class="card stat"><div class="label">LATEST STEPS</div><div class="value">${latest.steps==null?'—':f(latest.steps)}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">DAILY DISTANCE</div><div class="value">${latest.daily_distance_meters==null?'—':`${f(latest.daily_distance_meters/1000,1)} km`}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">LATEST SLEEP</div><div class="value">${latest.sleep_minutes==null?'—':`${Math.floor(latest.sleep_minutes/60)}h ${latest.sleep_minutes%60}m`}</div><small class="muted">${esc(latest.date)}</small></div><div class="card stat"><div class="label">LATEST HRV</div><div class="value">${latest.hrv_millis==null?'—':`${f(latest.hrv_millis)} ms`}</div><small class="muted">Estimate from synced device data</small></div></div>${card(`Steps · last ${recent.length} synced days`,`<div class="activity-bars">${bars}</div>`)}<br>${card('Running · last 7 days',weeklyRun)}<br>${card('Daily recovery history',`<div class="list">${list}</div><p class="muted small">Showing up to 30 synced days. Data is read from Health Connect on Android; a wearable must first sync with Health Connect. Recovery scores are informational, not medical assessments.</p>`)}`}
function visibleHomeWorkoutHistory(sessions,expanded=false){return expanded?(sessions||[]):(sessions||[]).slice(0,3)}
const onboardingGoals=['Build muscle','Build strength','Lose fat','General fitness','Improve consistency'];
const onboardingEquipment=['Barbell','Dumbbell','Bench','Cable','Machine','Resistance bands','Bodyweight'];
const onboardingDays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function renderOnboarding(){const o=state.onboarding||{},checks=(name,items,selected=[])=>items.map(x=>`<label class="onboarding-check"><input type="checkbox" name="${name}" value="${esc(x)}" ${selected.includes(x)?'checked':''}> ${esc(x)}</label>`).join('');root.innerHTML=`<main class="onboarding-shell"><div class="onboarding-brand"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><span class="pill">SET UP YOUR PLAN · REQUIRED</span></div><section class="auth-card onboarding-card"><h1>Build your training plan</h1><p class="muted">Complete these questions so your recommendations fit you. This setup is required before entering the app; you can change these details later in your profile.</p><form id="onboarding-form" class="stack"><h2>About you</h2><div class="form-grid"><div class="field"><label>Age (18 or older)</label><input class="input" name="ageYears" type="number" min="18" max="120" value="${esc(o.ageYears||'')}" required></div><div class="field"><label>Name (optional)</label><input class="input" name="name" maxlength="60" value="${esc(o.name||'')}"></div></div><div class="form-grid"><div class="field"><label>Units</label><select class="input" name="units"><option value="metric" ${(o.heightUnit||'cm')==='cm'?'selected':''}>Metric · kg / cm</option><option value="imperial" ${o.heightUnit==='in'?'selected':''}>Imperial · lb / in</option></select></div><div class="field"><label>Gender</label><select class="input" name="gender"><option ${!o.gender||o.gender==='Male'?'selected':''}>Male</option><option ${o.gender==='Female'?'selected':''}>Female</option></select></div></div><div class="form-grid"><div class="field"><label>Height (optional)</label><input class="input" name="height" type="number" min="1" max="300" step="0.1" value="${esc(o.height||'')}"></div><div class="field"><label>Weight (optional)</label><input class="input" name="weight" type="number" min="1" max="500" step="0.1" value="${esc(o.weight||'')}"></div></div><h2>Your goal</h2><div class="field"><label>Primary goal</label><select class="input" name="primaryGoal">${onboardingGoals.map(g=>`<option ${o.primaryGoal===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>Secondary goals (optional)</label><div class="onboarding-checks">${checks('secondaryGoals',onboardingGoals.filter(x=>x!==(o.primaryGoal||onboardingGoals[0])),o.secondaryGoals||[])}</div></div><h2>Training experience and equipment</h2><div class="form-grid"><div class="field"><label>Experience</label><select class="input" name="experienceLevel">${['Beginner','Intermediate','Advanced'].map(x=>`<option ${o.experienceLevel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Training location</label><select class="input" name="trainingLocation">${['Full gym','Home gym','Minimal equipment','Bodyweight only'].map(x=>`<option ${o.trainingLocation===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Available equipment (choose at least one)</label><div class="onboarding-checks">${checks('availableEquipment',onboardingEquipment,o.availableEquipment||['Barbell','Dumbbell','Bench','Cable','Machine'])}</div></div><h2>Your weekly schedule</h2><div class="field"><label>Workout goal</label><select class="input" name="sessionsPerWeek">${[2,3,4,5,6].map(x=>`<option value="${x}" ${n(o.sessionsPerWeek,3)===x?'selected':''}>${x} sessions per week</option>`).join('')}</select></div><label class="onboarding-check"><input type="checkbox" name="flexibleSchedule" ${o.flexibleSchedule!==false?'checked':''}> Flexible schedule; I’ll choose workout days as I go</label><div class="field"><label>Preferred days (if not flexible)</label><div class="onboarding-checks">${checks('trainingDays',onboardingDays,(o.trainingDays||[]).map(x=>typeof x==='number'?onboardingDays[x-1]:x))}</div></div><h2>Limitations (optional)</h2><div class="field"><div class="onboarding-checks">${checks('exerciseLimitations',['Shoulders','Back','Knees','Hips','Wrists or elbows'],o.exerciseLimitations||[])}</div></div><p class="notice">Stop any movement that causes pain. If you have an injury or medical condition, consult a qualified health professional before starting a new plan. This is not medical advice.</p><div class="message" role="status">${esc(state.message)}</div><button class="button primary" ${state.busy?'disabled':''}>${state.busy?'SAVING…':'SAVE AND CONTINUE'}</button></form></section></main>`}
async function saveOnboarding(form){const d=new FormData(form),age=Number(d.get('ageYears')),equipment=d.getAll('availableEquipment').map(String),target=Number(d.get('sessionsPerWeek')||3),flexible=d.has('flexibleSchedule'),days=d.getAll('trainingDays').map(x=>onboardingDays.indexOf(String(x))+1).filter(x=>x>0);if(!Number.isInteger(age)||age<18||age>120)throw new Error('The GodBuilder is currently for adults 18 and older.');if(!equipment.length)throw new Error('Choose at least one available piece of equipment.');if(!flexible&&days.length!==target)throw new Error(`Select ${target} training days, or choose a flexible schedule.`);const unit=d.get('units')==='imperial'?'in':'cm',weightUnit=d.get('units')==='imperial'?'lb':'kg',name=String(d.get('name')||'').trim()||'THE BUILDER',profile={email:state.session.user.email||'',name,gender:String(d.get('gender')||'Male'),path:'',height:String(d.get('height')||''),heightUnit:unit,weight:String(d.get('weight')||''),weightUnit,ageYears:age,primaryGoal:String(d.get('primaryGoal')||'Build muscle'),secondaryGoals:d.getAll('secondaryGoals').map(String),experienceLevel:String(d.get('experienceLevel')||'Beginner'),trainingLocation:String(d.get('trainingLocation')||'Full gym'),availableEquipment:equipment,sessionsPerWeek:target,trainingDays:days,flexibleSchedule:flexible,exerciseLimitations:d.getAll('exerciseLimitations').map(String),marketingOptIn:false};const row={id:state.session.user.id,display_name:name,name,gender:profile.gender,training_path:'',path:'',height_value:profile.height?Number(profile.height):null,height_unit:unit,weight_value:profile.weight?Number(profile.weight):null,weight_unit:weightUnit,marketing_opt_in:false,is_public:false,onboarding_data:{...profile,timeZone:state.timeZone}};state.busy=true;render();try{await db('profiles?on_conflict=id',{method:'POST',body:row,prefer:'resolution=merge-duplicates,return=minimal'});state.needsOnboarding=false;state.onboarding={};state.profile=row;state.busy=false;state.message='';state.pendingRecommendedPlan=generateRecommendedPlan(profile,state.session.user.id);localStorage.setItem(pendingPlanKey(state.session.user.id),JSON.stringify(state.pendingRecommendedPlan));state.page='plan-review';state.busy=false;render()}catch(e){state.busy=false;throw e}}
function recommendationCatalog(){const body=[['Push-Up','Chest','Bodyweight'],['Bodyweight Squat','Legs','Bodyweight'],['Glute Bridge','Glutes','Bodyweight'],['Plank','Core','Bodyweight'],['Band Row','Back','Resistance bands'],['Band Biceps Curl','Biceps','Resistance bands'],['Band Triceps Pressdown','Triceps','Resistance bands'],['Dumbbell Romanian Deadlift','Hamstrings','Dumbbell'],['Goblet Squat','Legs','Dumbbell'],['One-Arm Dumbbell Row','Back','Dumbbell'],['Dumbbell Bench Press','Chest','Dumbbell'],['Dumbbell Shoulder Press','Shoulders','Dumbbell'],['Dumbbell Curl','Biceps','Dumbbell'],['Lateral Raise','Shoulders','Dumbbell'],['Barbell Bench Press','Chest','Barbell'],['Barbell Squat','Legs','Barbell'],['Romanian Deadlift','Hamstrings','Barbell'],['Barbell Row','Back','Barbell'],['Overhead Press','Shoulders','Barbell'],['Lat Pulldown','Back','Cable'],['Seated Cable Row','Back','Cable'],['Triceps Pushdown','Triceps','Cable'],['Leg Press','Legs','Machine'],['Chest Press Machine','Chest','Machine'],['Leg Curl Machine','Hamstrings','Machine']];const all=[...body,...exerciseChoices];return [...new Map(all.map(x=>[String(x[0]).toLowerCase(),x])).values()]}
function recommendationCautions(exercise){const name=exercise[0].toLowerCase(),muscle=exercise[1].toLowerCase(),tags=[];if(['chest','shoulders','triceps'].includes(muscle)||/push|press|fly|dip|lateral raise/.test(name))tags.push('shoulders','wrists or elbows');if(['back','hamstrings'].includes(muscle)||/row|deadlift|plank/.test(name))tags.push('back','wrists or elbows');if(['legs','quads'].includes(muscle)||/squat|lunge|leg press/.test(name))tags.push('knees','back','hips');if(['glutes'].includes(muscle)||/glute|hip thrust/.test(name))tags.push('back','hips');if(['biceps'].includes(muscle)||/curl/.test(name))tags.push('wrists or elbows');return new Set(tags)}
function generateRecommendedPlan(profile,userId=state.session?.user?.id||''){const goal=String(profile.primaryGoal||'Build muscle'),experience=String(profile.experienceLevel||'Beginner'),count=Math.max(2,Math.min(6,Number(profile.sessionsPerWeek)||3)),available=new Set((profile.availableEquipment||[]).map(x=>String(x).toLowerCase()));available.add('bodyweight');const limitations=new Set((profile.exerciseLimitations||[]).map(x=>String(x).toLowerCase())),strength=goal.toLowerCase()==='build strength',repMin=strength?5:8,repMax=strength?8:12;const catalog=recommendationCatalog();const allowed=catalog.filter(e=>available.has(String(e[2]).toLowerCase())&&![...recommendationCautions(e)].some(t=>limitations.has(t)));const focus=name=>name.startsWith('FULL BODY')?['Legs','Chest','Back','Shoulders','Core']:name.startsWith('UPPER')?['Chest','Back','Shoulders','Biceps','Triceps']:name.startsWith('LOWER')||name.startsWith('LEGS')?['Legs','Hamstrings','Glutes','Core']:name.startsWith('PUSH')?['Chest','Shoulders','Triceps']:name.startsWith('PULL')?['Back','Biceps','Shoulders']:['Legs','Chest','Back','Core'];const splits=count<=3?Array.from({length:count},(_,i)=>`FULL BODY ${String.fromCharCode(65+i)}`):count===4?['UPPER A','LOWER A','UPPER B','LOWER B']:count===5?['PUSH','PULL','LEGS','UPPER','LOWER']:['PUSH A','PULL A','LEGS A','PUSH B','PULL B','LEGS B'];return splits.map((title,day)=>{const seen=new Set(),picked=[];for(const muscle of focus(title)){const options=allowed.filter(x=>x[1].toLowerCase()===muscle.toLowerCase()&&!seen.has(x[0]));if(!options.length)continue;const item=options[(day+picked.length)%options.length];seen.add(item[0]);picked.push(item)}const exercises=picked.map(([name,muscleGroup,equipment])=>({id:uid(),exercise:{id:uid(),name,muscleGroup,equipment},restTimerSeconds:['Legs','Hamstrings','Glutes'].includes(muscleGroup)?90:60,notes:'',targetRepMin:repMin,targetRepMax:repMax,weightIncrementKg:2.5,sets:Array.from({length:3},(_,i)=>({id:uid(),setNumber:i+1,setType:'WORKING',targetWeightKg:0,targetReps:repMin}))}));const beginner=experience.toLowerCase()==='beginner';return{id:uid(),userId,isCustom:false,title,notes:`Recommended for ${experience.toLowerCase()} training with the goal “${goal}”. Uses selected equipment and avoids the limitations you reported. ${beginner?'Start light and focus on comfortable technique.':'Review the movements and adjust loads to your experience.'}`,definition:{id:uid(),userId,isCustom:false,title,notes:'',folder:'RECOMMENDED',exercises}}})}
function renderPlanReview(){const plan=state.pendingRecommendedPlan||[],onboarding=state.profile?.onboarding_data||{};const cards=plan.map((r,i)=>`<article class="card"><div class="row between"><div><div class="kicker">SESSION ${i+1}</div><h2>${esc(r.title)}</h2></div><span class="pill">${r.definition.exercises.length} EXERCISES</span></div><p class="muted small">${esc(r.notes)}</p><div class="list">${r.definition.exercises.map(x=>`<div class="list-row"><div><strong>${esc(x.exercise.name)}</strong><small>${esc(x.exercise.muscleGroup)} · ${esc(x.exercise.equipment)}</small></div><span class="pill">3 × ${x.targetRepMin}–${x.targetRepMax}</span></div>`).join('')||'<p class="muted small">No safe movement matched the selected equipment and limitations. You can customize this session in Workouts.</p>'}</div></article>`).join('');root.innerHTML=`<main class="onboarding-shell"><div class="onboarding-brand"><div class="brand"><small>THE</small><strong>GODBUILDER</strong></div><span class="pill">PERSONALIZED STARTER PLAN</span></div><section class="auth-card onboarding-card"><div class="kicker">${esc(onboarding.sessionsPerWeek||plan.length)} SESSIONS PER WEEK · ${esc(onboarding.primaryGoal||'YOUR GOAL')}</div><h1>Your starting plan</h1><p class="muted">Built around your experience, equipment and reported limitations. Review it before training; you can change any routine later.</p><div class="grid two">${cards}</div><div class="row" style="margin-top:16px"><button class="button" data-action="customize-recommended-plan">CUSTOMIZE IN WORKOUTS</button><button class="button primary" data-action="accept-recommended-plan">SAVE STARTER PLAN</button></div></section></main>`}
async function acceptRecommendedPlan(){const plan=state.pendingRecommendedPlan||[];if(!plan.length)throw new Error('No recommended plan is ready. Complete your training profile first.');const rows=plan.map(r=>({id:r.id,user_id:state.session.user.id,title:r.title,notes:r.notes,definition:r.definition}));await db('routines?on_conflict=id',{method:'POST',body:rows,prefer:'resolution=merge-duplicates,return=minimal'});state.pendingRecommendedPlan=null;localStorage.removeItem(pendingPlanKey(state.session.user.id));state.page='home';await refreshData();flash('Your recommended starter plan is saved in Workouts.')}
