function nutritionGoalSuggestion({age=30,heightCm=175,weightKg=70,calculationSex='Male',activityLevel=1.375,goalType='Maintain'}){const bmr=10*weightKg+6.25*heightCm-5*age+(calculationSex==='Male'?5:-161),maintenance=Math.max(800,Math.min(10000,Math.round(bmr*activityLevel))),ranges={ 'Fat loss':{calories:[Math.max(800,maintenance-500),Math.max(800,maintenance-250)],protein:[1.8,2.2],factor:2}, 'Muscle gain':{calories:[Math.min(10000,maintenance+150),Math.min(10000,maintenance+300)],protein:[1.6,2.0],factor:1.8}, Recomp:{calories:[Math.max(800,maintenance-150),Math.min(10000,maintenance+100)],protein:[1.8,2.2],factor:2}, Maintain:{calories:[Math.max(800,maintenance-100),Math.min(10000,maintenance+100)],protein:[1.6,2.0],factor:1.7} },range=ranges[goalType]||ranges.Maintain,calories=Math.max(800,Math.min(10000,Math.round(goalType==='Fat loss'?maintenance-350:goalType==='Muscle gain'?maintenance+200:maintenance))),protein=Math.max(1,Math.round(weightKg*range.factor)),fat=Math.max(1,Math.round(weightKg*.8)),carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4));return{maintenance,calories,protein,carbs,fat,calorieRange:range.calories,proteinRange:[Math.round(weightKg*range.protein[0]),Math.round(weightKg*range.protein[1])]}}
