modal.addEventListener('input',event=>{if(event.target.id==='exercise-search'){const target=modal.querySelector('#exercise-results');if(target)target.innerHTML=exerciseOptionsHtml(event.target.value)}if(event.target.id==='replace-exercise-search'){const target=modal.querySelector('#replace-exercise-results');if(target)target.innerHTML=replacementChoicesHtml(state.replaceExerciseIndex,event.target.value,modal.querySelector('#replace-equipment-filter')?.value||'All')}});
modal.addEventListener('change',event=>{if(event.target.name==='exercises'){const selected=[...modal.querySelectorAll('#routine-form [name="exercises"]:checked')].map(x=>Number(x.value)),settings=modal.querySelector('#strength-plan-settings');if(settings)settings.hidden=selected.length>0&&selected.every(i=>exerciseChoices[i]?.[2]==='Activity')}if(['exercise-muscle-filter','exercise-equipment-filter'].includes(event.target.id)){const target=modal.querySelector('#exercise-results');if(target)target.innerHTML=exerciseOptionsHtml(modal.querySelector('#exercise-search')?.value||'')}if(event.target.id==='replace-equipment-filter'){const target=modal.querySelector('#replace-exercise-results');if(target)target.innerHTML=replacementChoicesHtml(state.replaceExerciseIndex,modal.querySelector('#replace-exercise-search')?.value||'',event.target.value)}});
