modal.addEventListener('change',event=>{if(event.target.closest('#nutrition-goal-form'))updateNutritionGoalPreview()});
root.addEventListener('submit',event=>{if(event.target.id==='auth-form'){event.preventDefault();const d=Object.fromEntries(new FormData(event.target));const email=String(d.email).trim();if(state.authMode==='reset-email')requestPasswordReset(email);else signIn(email,String(d.password),state.authMode==='signup')}else if(event.target.id==='password-recovery-form'){event.preventDefault();const d=Object.fromEntries(new FormData(event.target));completePasswordReset(String(d.password),String(d.confirmPassword)).catch(handleError)}});
async function saveProfile(){const id=state.session.user.id,old=state.profile||{},requestedZone=String(document.querySelector('#profile-time-zone').value||'').trim(),weightText=String(document.querySelector('#profile-weight').value||'').trim(),weightUnit=document.querySelector('#profile-weight-unit').value;try{new Intl.DateTimeFormat('en',{timeZone:requestedZone})}catch{throw new Error('Enter a valid time zone such as Asia/Kolkata or America/New_York.')}let weightValue=null;if(weightText){weightValue=Number(weightText);const weightKg=weightUnit==='lb'?weightValue/2.2046226218:weightValue;if(!Number.isFinite(weightKg)||weightKg<30||weightKg>350)throw new Error('Enter a body weight that converts to 30–350 kg.')}const onboarding={...(old.onboarding_data||{}),sessionsPerWeek:n(document.querySelector('#profile-goal').value,3),timeZone:requestedZone};const row={id,display_name:formValue('profile-name')||'THE BUILDER',name:formValue('profile-name')||'THE BUILDER',gender:document.querySelector('#profile-gender').value,training_path:document.querySelector('#profile-path').value,path:document.querySelector('#profile-path').value,height_unit:old.height_unit||'cm',weight_value:weightValue,weight_unit:weightUnit,marketing_opt_in:old.marketing_opt_in||false,is_public:old.is_public||false,onboarding_data:onboarding};await db('profiles?on_conflict=id',{method:'POST',body:row,prefer:'resolution=merge-duplicates,return=minimal'});state.timeZone=requestedZone;localStorage.setItem('gbNutritionTimeZone',requestedZone);await refreshData();flash('Profile saved.')}
function chooseUsername(){if(state.username){flash(`Your community username is @${esc(state.username)}.`);return}openModal('Choose a username',`<form id="username-form">${field('Username','username','text','','required minlength="3" maxlength="20" pattern="[a-z][a-z0-9_]{2,19}" autocomplete="username"')}<p class="muted small">Start with a letter. Use 3–20 lowercase letters, numbers or underscores.</p></form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-username">CLAIM USERNAME</button>`)}
async function saveUsername(){const form=modal.querySelector('#username-form');if(!form.reportValidity())return;const value=String(new FormData(form).get('username')||'').trim().toLowerCase();if(!/^[a-z][a-z0-9_]{2,19}$/.test(value))throw new Error('Start with a letter and use 3–20 lowercase letters, numbers or underscores.');await rpc('claim_username',{p_username:value});state.username=value;if(state.profile)state.profile={...state.profile,username:value};closeModal();flash(`Your username is @${value}.`)}
async function loadUserName(){if(state.username||state.usernameLoading)return;state.usernameLoading=true;try{const rows=await db('usernames',{query:`select=username&user_id=eq.${encodeURIComponent(state.session.user.id)}&limit=1`});state.username=rows?.[0]?.username||'';if(state.profile)state.profile={...state.profile,username:state.username};render()}finally{state.usernameLoading=false}}
async function setPublic(value){const isPublic=Boolean(value);await db('profiles',{method:'PATCH',query:`id=eq.${encodeURIComponent(state.session.user.id)}`,body:{is_public:isPublic},prefer:'return=minimal'});state.profile={...(state.profile||{}),is_public:isPublic};flash(isPublic?'Profile is public.':'Profile is private.');render()}
document.addEventListener('submit',event=>{if(event.target.id==='food-form'){event.preventDefault();}if(event.target.id==='routine-form')event.preventDefault();if(event.target.id==='workout-form')event.preventDefault();if(event.target.id==='quantity-form')event.preventDefault()});
// Community data is loaded through the same authenticated, RLS-protected RPCs as Android.
state.challengeEntries = state.challengeEntries || {};
state.publicProfiles = state.publicProfiles || [];
state.publicRoutines = state.publicRoutines || [];
state.activeClan = state.activeClan || null;
async function loadChallenges(clanId){const target=clanId||state.activeClan?.id;if(!target)return;state.activeClan=state.clans.find(c=>c.id===target)||state.activeClan;state.challenges=await db('clan_challenges',{query:`select=*&clan_id=eq.${encodeURIComponent(target)}&order=expires_at.asc`});state.challengeEntries={};for(let i=0;i<state.challenges.length;i+=8){await Promise.all(state.challenges.slice(i,i+8).map(async c=>{state.challengeEntries[c.id]=await rpc('challenge_entries',{p_id:c.id}).catch(()=>[])}))}render()}
async function showClan(clan){state.activeClan=clan;await loadChallenges(clan.id)}
function renderCommunity(){
  const clans=state.clans.map(c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.gym_name||'Independent Clan')} · ${n(c.member_count)} members</small><small>Invite code <b class="gold">${esc(c.invite_code)}</b></small></div><button class="button" data-action="open-clan" data-id="${esc(c.id)}">OPEN</button></div>`).join('')||`<div class="empty">No Clans yet. Build one or join with an invite code.</div>`;
  const unread=state.notices.filter(x=>!x.read_at).map(x=>`<div class="list-row"><div><strong>${esc(x.message)}</strong><small>${new Date(x.created_at).toLocaleString()}</small></div><button class="button" data-action="mark-notice-read" data-id="${esc(x.id)}">MARK READ</button></div>`).join('');
  const challenges=state.activeClan?(state.challenges||[]).map(ch=>{const entries=state.challengeEntries?.[ch.id]||[];const board=entries.map((e,i)=>`<div class="list-row"><span><b class="gold">${i+1}.</b> ${esc(e.display_name)}</span><strong>${f(e.best_weight,1)} ${esc(ch.weight_unit)}</strong></div>`).join('')||`<p class="muted small">No results yet. Be the first to log a lift.</p>`;return `<section class="card"><div class="row between"><div><h3>${esc(ch.lift_name)}</h3><p class="muted small">Target ${f(ch.target_weight,1)} ${esc(ch.weight_unit)} · ends ${new Date(ch.expires_at).toLocaleDateString()}</p></div><button class="button primary" data-action="log-challenge" data-id="${esc(ch.id)}" ${new Date(ch.expires_at)<=new Date()?'disabled':''}>LOG RESULT</button></div><h3>LEADERBOARD</h3><div class="list">${board}</div></section>`}).join('')||`<div class="empty">No lift challenges yet. Start one for your Clan.</div>`:'';
  const profiles=(state.publicProfiles||[]).map(p=>`<div class="list-row"><div><strong>${esc(p.display_name)}</strong><small>@${esc(p.username||'')} · ${esc(p.training_path||'BUILDER')}</small></div><button class="button" data-action="view-public-profile" data-id="${esc(p.user_id)}">VIEW WORKOUTS</button></div>`).join('')||`<div class="empty">Search for public profiles by username or display name.</div>`;
  const publicRoutines=(state.publicRoutines||[]).map(r=>`<div class="list-row"><div><strong>${esc(r.title)}</strong><small>${(r.definition?.exercises||[]).length} exercises</small></div><button class="button primary" data-action="copy-public-routine" data-id="${esc(r.id)}">COPY WORKOUT</button></div>`).join('');
  const coaching=(state.coachRelationships||[]).map(r=>{const athlete=r.athlete_id===state.session.user.id,person=athlete?r.coach_name:r.athlete_name,username=athlete?r.coach_username:r.athlete_username,busy=state.coachRespondingId===r.id;const actions=r.status==='pending'&&!athlete?`<button class="button primary" data-action="respond-coach-request" data-id="${esc(r.id)}" data-accept="true" ${state.coachRespondingId?'disabled':''}>${busy?'ACCEPTING…':'ACCEPT'}</button><button class="button" data-action="respond-coach-request" data-id="${esc(r.id)}" data-accept="false" ${state.coachRespondingId?'disabled':''}>DECLINE</button>`:r.status==='pending'&&athlete?`<button class="button" data-action="end-coach-relationship" data-id="${esc(r.id)}">CANCEL REQUEST</button>`:r.status==='active'&&!athlete?`<button class="button primary" data-action="create-coached-workout" data-id="${esc(r.athlete_id)}" data-name="${esc(person)}">CREATE WORKOUT</button><button class="button danger" data-action="end-coach-relationship" data-id="${esc(r.id)}">END CONNECTION</button>`:r.status==='active'?`<button class="button danger" data-action="end-coach-relationship" data-id="${esc(r.id)}">END CONNECTION</button>`:'';const status=r.status==='pending'?(athlete?'Request pending':'Wants you as coach'):r.status==='active'?(athlete?'Your coach':'Your athlete'):r.status;return `<article class="coach-relationship"><div class="coach-person"><strong>${esc(person||'Community member')}</strong><small>${username?`@${esc(username)} · `:''}${esc(status)}</small></div><div class="coach-actions">${actions}</div></article>`}).join('')||'<div class="empty">No coach connections yet.</div>';
  return `${head('THE GATHERING','Community','Build a Clan, challenge lifts, and share routines.',`<button class="button primary" data-action="create-clan">+ BUILD A CLAN</button>`)}${unread?card('Inbox',`<div class="list">${unread}</div>`):''}${card('Coach & athlete',`<p class="muted small">Request a coach by username. A coach can create workouts for you only after you accept; your history and health data stay private.</p><form id="coach-request-form" class="row"><input class="input" name="username" placeholder="Coach username" minlength="3" maxlength="20" required><button type="button" class="button primary" data-action="request-coach">REQUEST</button></form><div class="list" style="margin-top:10px">${coaching}</div>`)}<div class="grid two">${card('Your Clans',`<div class="list">${clans}</div><div class="row" style="margin-top:12px"><button class="button" data-action="join-clan">JOIN WITH CODE</button></div>`)}${card('Username & profile visibility',`<p class="muted small">Set a username so friends can find you. Enabling public discovery makes your saved workouts visible for friends to copy.</p><div class="row"><span class="gold">${state.username?`@${esc(state.username)}`:'No username set'}</span><button class="button" data-action="set-username" ${state.username?'disabled':''}>${state.username?'USERNAME SET':'CHOOSE USERNAME'}</button></div><label class="row" style="margin-top:14px"><input type="checkbox" data-action="toggle-public" ${state.profile?.is_public?'checked':''}> <span class="small">Allow my profile and saved workouts to be found</span></label>`)}${card('Find public workouts',`<form id="public-search-form" class="row"><input class="input" name="query" placeholder="Username or display name" maxlength="40"><button class="button" data-action="search-public">SEARCH</button></form><div class="list" style="margin-top:8px">${profiles}</div>${state.viewedProfile?`<h3 style="margin-top:16px">${esc(state.viewedProfile.display_name||'')}’S WORKOUTS</h3><div class="list">${publicRoutines||'<div class="empty">No saved workouts to share yet.</div>'}</div>`:''}`)}</div>${state.activeClan?`<section style="margin-top:20px"><div class="page-head"><div><div class="kicker">CLAN CHALLENGES</div><h2>${esc(state.activeClan.name)}</h2><p>Invite code <b class="gold">${esc(state.activeClan.invite_code)}</b></p></div><button class="button primary" data-action="create-challenge" data-id="${esc(state.activeClan.id)}">+ CHALLENGE A LIFT</button></div><div class="grid two">${challenges}</div></section>`:''}`
}
async function searchPublicProfiles(){const form=document.querySelector('#public-search-form');const query=String(new FormData(form).get('query')||'').trim().slice(0,40);if(query.length<2)throw new Error('Enter at least two characters to search.');state.publicProfiles=await rpc('search_public_profiles',{p_query:query});state.publicRoutines=[];state.viewedProfile=null;render()}
async function viewPublicProfile(userId){const profile=state.publicProfiles.find(p=>p.user_id===userId);if(!profile)return;state.viewedProfile=profile;state.publicRoutines=await db('routines',{query:`select=id,user_id,title,notes,definition&user_id=eq.${encodeURIComponent(userId)}&order=updated_at.desc`});render()}
async function copyPublicRoutine(id){const row=state.publicRoutines.find(r=>r.id===id);if(!row)throw new Error('That workout is no longer available.');const def=structuredClone(row.definition||{});def.id=uid();def.userId=state.session.user.id;def.isCustom=true;def.title=`Copy · ${String(row.title||def.title||'Workout').slice(0,60)}`;def.exercises=(def.exercises||[]).map(e=>({...e,id:uid(),exercise:{...e.exercise,id:uid()},sets:(e.sets||[]).map(s=>({...s,id:uid()}))}));await db('routines?on_conflict=id',{method:'POST',body:{id:def.id,user_id:state.session.user.id,title:def.title,notes:def.notes||'',definition:def},prefer:'resolution=merge-duplicates,return=minimal'});await refreshData();state.page='workouts';flash('Workout copied to your saved workouts.')}
async function markNoticeRead(id){await db('clan_notifications',{method:'PATCH',query:`id=eq.${encodeURIComponent(id)}&user_id=eq.${encodeURIComponent(state.session.user.id)}`,body:{read_at:new Date().toISOString()},prefer:'return=minimal'});state.notices=state.notices.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x);render()}
async function respondToCoachRequest(id,accept){if(!id||state.coachRespondingId)return;state.coachRespondingId=id;state.message='';render();try{await rpc('respond_coach_request',{p_relationship_id:id,p_accept:accept});await refreshData();flash(accept?'Coach request accepted.':'Coach request declined.')}catch(error){handleError(new Error(error?.message||'Couldn’t update the coach request. Check your connection and try again.'))}finally{state.coachRespondingId=null}}
function submitChallengeResult(id){const challenge=state.challenges.find(x=>x.id===id);if(!challenge)throw new Error('Challenge not found.');openModal('Log lift result',`<form id="challenge-result-form">${field(`Best ${esc(challenge.lift_name)} (${esc(challenge.weight_unit)})`,'weight','number','','required min="0.5" step="0.5"')}</form>`,`<button class="button" data-action="close-modal">CANCEL</button><button class="button primary" data-action="save-challenge-result" data-id="${esc(id)}">SUBMIT RESULT</button>`)}
async function saveChallengeResult(id){const form=modal.querySelector('#challenge-result-form');if(!form.reportValidity())return;const weight=n(new FormData(form).get('weight'));await rpc('log_challenge_result',{p_challenge_id:id,p_best_weight:weight});closeModal();await loadChallenges(state.activeClan.id);flash('Result submitted. The leaderboard is updated.')}
root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['open-clan','search-public','view-public-profile','copy-public-routine','mark-notice-read','log-challenge','save-challenge-result'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();const run=async()=>{if(action==='open-clan'){const c=state.clans.find(x=>x.id===el.dataset.id);if(c)await showClan(c)}else if(action==='search-public')await searchPublicProfiles();else if(action==='view-public-profile')await viewPublicProfile(el.dataset.id);else if(action==='copy-public-routine')await copyPublicRoutine(el.dataset.id);else if(action==='mark-notice-read')await markNoticeRead(el.dataset.id);else if(action==='log-challenge')submitChallengeResult(el.dataset.id);else if(action==='save-challenge-result')await saveChallengeResult(el.dataset.id)};run().catch(handleError)},true);
modal.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['save-username','save-challenge-result'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();const run=action==='save-username'?saveUsername():saveChallengeResult(el.dataset.id);Promise.resolve(run).catch(handleError)},true);
document.addEventListener('submit',event=>{if(event.target.id==='public-search-form')event.preventDefault()});
modal.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;if(handleActiveWorkoutAction(el.dataset.action,el)){event.preventDefault();event.stopImmediatePropagation()}},true);

function avatarUnlockedForLevel(level){return Number.isFinite(Number(level))&&Number(level)>=2}
function avatarUnlockedForXp(xp){return Number.isFinite(Number(xp))&&Number(xp)>=1000}
function normalizeAvatarDimensions(raw={}){const keys=['heightPct','buildPct','shouldersPct','chestPct','armsPct','waistPct','hipsPct','thighsPct','calvesPct'];return Object.fromEntries(keys.map(key=>[key,Math.max(80,Math.min(120,n(raw?.[key],100)))]))}
function avatarDimensionMask(y,start,end,fade){const smooth=value=>{const t=Math.max(0,Math.min(1,value));return t*t*(3-2*t)};return smooth((y-start)/fade)*smooth((end-y)/fade)}
function avatarWidthScaleAt(y,raw){const d=normalizeAvatarDimensions(raw),band=Math.max(0,Math.min(1,y)),regional=(d.shouldersPct-100)*avatarDimensionMask(band,.19,.38,.065)+(d.chestPct-100)*avatarDimensionMask(band,.28,.49,.065)+(d.armsPct-100)*avatarDimensionMask(band,.22,.59,.07)*.55+(d.waistPct-100)*avatarDimensionMask(band,.40,.59,.07)+(d.hipsPct-100)*avatarDimensionMask(band,.50,.69,.065)+(d.thighsPct-100)*avatarDimensionMask(band,.60,.83,.07)+(d.calvesPct-100)*avatarDimensionMask(band,.76,.97,.06);return Math.max(.70,Math.min(1.45,d.buildPct/100+regional/100))}
function renderAvatarMorphCanvases(){const dims=normalizeAvatarDimensions(state.avatarDimensionsDraft||state.profile?.onboarding_data?.avatarDimensions);for(const canvas of root.querySelectorAll('canvas[data-avatar-morph]')){const img=canvas._avatarImage;if(!img?.complete||!img.naturalWidth)continue;const ctx=canvas.getContext('2d');if(!ctx)continue;const w=img.naturalWidth,h=img.naturalHeight,vertical=dims.heightPct/100,fit=Math.min(canvas.width/w,canvas.height/(h*vertical)),baseW=w*fit,displayH=h*fit*vertical,top=(canvas.height-displayH)/2,bands=Math.min(h,384);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.imageSmoothingEnabled=true;for(let i=0;i<bands;i++){const sy=Math.floor(i*h/bands),end=Math.min(h,Math.floor((i+1)*h/bands)),sh=Math.max(1,end-sy),scale=avatarWidthScaleAt((sy+end)/2/h,dims),dw=baseW*scale,dh=displayH*sh/h;ctx.drawImage(img,0,sy,w,sh,(canvas.width-dw)/2,top+displayH*sy/h,dw,dh+1)}}}
function renderAvatar(){const p=state.profile||{},xp=xpForSessions(state.sessions,targetPerWeek()),level=Math.floor(xp/1000)+1,unlocked=avatarUnlockedForXp(xp),stage=level>=10?3:level>=5?2:1,path=['SUPERHERO','TITAN'].includes(String(p.training_path||'').toUpperCase())?String(p.training_path).toLowerCase():'god',gender=avatarPresentation(p),base=`${config.supabaseUrl.replace(/\/$/,'')}/storage/v1/object/public/godbuilder-site/avatarpack`;state.avatarDimensionsDraft=normalizeAvatarDimensions(p.onboarding_data?.avatarDimensions);const choices=[['GOD','God'],['SUPERHERO','Superhero'],['TITAN','Titan']].map(([kind,label])=>[kind,gender,`${label} · ${gender==='female'?'Female':'Male'}`]);const image=(kind,sex,levelStage,extra='',morph=false,locked=false)=>{if(locked)return `<div class="avatar-art ${extra} locked" role="img" aria-label="${kind} ${sex} avatar locked until Level 2"><span class="avatar-locked-content"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg><b>AVATAR LOCKED</b><small>LEVEL 2 REQUIRED</small></span></div>`;const src=`${base}/avatar_${kind}_${sex}_stage_${levelStage}.png`;return `<div class="avatar-art ${extra}"><img class="avatar-base" src="${src}" alt="${kind} ${sex} avatar, stage ${levelStage}" loading="lazy" onerror="this.parentElement.classList.add('unavailable')">${morph?`<canvas class="avatar-morph" data-avatar-morph data-src="${src}" width="512" height="768" aria-label="Adjustable ${kind} ${sex} avatar"></canvas>`:''}<span class="avatar-fallback" aria-hidden="true">${kind}<small>${sex.toUpperCase()}</small></span></div>`};const modelCards=choices.map(([kind,sex,label])=>`<article class="avatar-choice ${kind.toLowerCase()===path&&sex===gender?'selected':''}">${image(kind.toLowerCase(),sex,1,'',false,!unlocked)}<div><strong>${label}</strong><small>${unlocked?(kind.toLowerCase()===path&&sex===gender?'CURRENT MODEL':'Set in Profile'):'LOCKED · LEVEL 2'}</small></div></article>`).join('');const basic=[['heightPct','Height'],['buildPct','Build'],['shouldersPct','Shoulders'],['waistPct','Waist']],advanced=[['chestPct','Chest'],['armsPct','Arms'],['hipsPct','Hips'],['thighsPct','Thighs'],['calvesPct','Calves']],dims=state.avatarDimensionsDraft,slider=([key,label])=>`<label class="dimension-control"><span>${label}<b data-dimension-value="${key}">${dims[key]}%</b></span><input type="range" min="80" max="120" step="5" value="${dims[key]}" data-avatar-dimension="${key}" aria-label="${label} proportion"></label>`;const editor=level<5?`<div class="locked-editor"><b>LEVEL 5 · BASIC EDITOR</b><p>Height, build, shoulders and waist unlock at Level 5. Advanced dimensions unlock at Level 10.</p></div>`:`<div class="avatar-dimension-grid">${basic.map(slider).join('')}${level>=10?`<div class="dimension-advanced"><b>ADVANCED · LEVEL 10</b>${advanced.map(slider).join('')}</div>`:`<div class="dimension-locked"><b>ADVANCED · LEVEL 10</b><small>Chest, arms, hips, thighs and calves unlock at Level 10.</small></div>`}</div><div class="row dimension-actions"><button class="button" data-action="reset-avatar-dimensions">RESET</button><button class="button primary" data-action="save-avatar-dimensions">SAVE MODEL</button></div>`;return `${head('AVATAR','Your avatar','Your training path, level and recovery journey in one place.')}<div class="grid two"><section class="card avatar-current"><div class="kicker">${esc(String(p.training_path||'GOD').toUpperCase())} PATH · ${gender.toUpperCase()}</div>${image(path,gender,stage,'avatar-main-art',true,!unlocked)}<h2>${unlocked?`LEVEL ${level} · STAGE ${stage}`:'AVATAR LOCKED · LEVEL 2'}</h2><p class="muted small">${unlocked?`${f(xp)} total XP · ${stage===1?`${Math.max(0,4000-xp)} XP to Stage 2`:stage===2?`${Math.max(0,9000-xp)} XP to Stage 3`:'Stage 3 reached'}`:`${f(xp)} / 1,000 XP · ${Math.max(0,1000-xp)} XP to unlock`}</p><div class="progress"><i style="width:${stage===1?Math.min(100,xp/40):stage===2?Math.min(100,(xp-4000)/50):100}%"></i></div><p class="muted small">${unlocked?'Your avatar follows your gender and training path. New stage artwork downloads on demand and stays cached on this device.':'Complete workouts to earn XP. All three paths for your selected presentation unlock when you reach Level 2.'}</p><button class="button" data-nav="profile">EDIT PATH & PRESENTATION</button></section>${card(`Your ${gender} avatar paths`,`<p class="muted small">These three cards match your selected presentation. The stage shown here follows your workout XP.</p><div class="avatar-grid">${modelCards}</div>`)}</div><section class="card avatar-dimensions-card"><div class="row between"><div><div class="kicker">AVATAR FORGE</div><h2>Dimensions editor</h2><p class="muted small">Shape the downloaded artwork. This changes appearance only, not workout or health data.</p></div><span class="pill">${level<5?'UNLOCKS AT 5':level<10?'BASIC · ADVANCED AT 10':'FULL EDITOR'}</span></div>${editor}</section>`}
function physioConsultationContent(){return `<section class="stack"><div><strong>Dhruv Bawa, MPT (Neurology)</strong><p class="muted small">Registered Physiotherapist · Haryana State Council of Physiotherapy · Registration No. HSCP/PT/2025/3685</p><p class="muted small">Master’s degree in Neurological Physiotherapy. Specialties include neurological and stroke rehabilitation; spinal cord injury; Parkinson’s and geriatric rehabilitation; cognitive rehabilitation; musculoskeletal, neck, back, shoulder and knee care; post-surgical rehabilitation; gait, balance and functional training.</p><p class="muted small">English · Hindi · Punjabi</p><p class="muted small">Service area: India and online worldwide, subject to local regulations.</p></div><hr><div><strong>Written exercise consultation</strong><p class="muted small">Discuss symptoms, receive personalized exercises and a home program, and get progression guidance.</p><span class="pill">PAID SERVICE · COMING SOON</span></div><div><strong>Live video consultation</strong><p class="muted small">One-to-one consultation with rehabilitation history, functional screening, exercise guidance and follow-up.</p><span class="pill">PAID SERVICE · COMING SOON</span></div><div class="notice">Consultations are not bookable yet. Pricing will be shown before launch.</div></section>`}
const dispatchActionBeforeAvatarEditor=dispatchAction;dispatchAction=async function(action,el){if(action==='reset-avatar-dimensions'){state.avatarDimensionsDraft=normalizeAvatarDimensions();for(const input of root.querySelectorAll('[data-avatar-dimension]')){input.value='100';const out=root.querySelector(`[data-dimension-value="${input.dataset.avatarDimension}"]`);if(out)out.textContent='100%'}renderAvatarMorphCanvases();return}if(action==='save-avatar-dimensions'){if(Math.floor(xpForSessions(state.sessions,targetPerWeek())/1000)+1<5)throw new Error('Reach Level 5 to unlock avatar dimensions.');const dims=normalizeAvatarDimensions(state.avatarDimensionsDraft),onboarding={...(state.profile?.onboarding_data||{}),avatarDimensions:dims};await db('profiles',{method:'PATCH',query:`id=eq.${encodeURIComponent(state.session.user.id)}`,body:{onboarding_data:onboarding},prefer:'return=minimal'});state.profile={...state.profile,onboarding_data:onboarding};state.avatarDimensionsDraft=dims;await refreshData();flash('Avatar dimensions saved to your profile.');return}return dispatchActionBeforeAvatarEditor(action,el)};
root.addEventListener('input',event=>{const input=event.target.closest('[data-avatar-dimension]');if(!input)return;const key=input.dataset.avatarDimension;state.avatarDimensionsDraft=normalizeAvatarDimensions({...state.avatarDimensionsDraft,[key]:Number(input.value)});const output=root.querySelector(`[data-dimension-value="${key}"]`);if(output)output.textContent=`${state.avatarDimensionsDraft[key]}%`;renderAvatarMorphCanvases()});
root.addEventListener('load',event=>{if(event.target.matches?.('img.avatar-base')){const canvas=event.target.parentElement.querySelector('canvas[data-avatar-morph]');if(!canvas)return;const img=new Image();img.crossOrigin='anonymous';img.onload=()=>{canvas._avatarImage=img;canvas.parentElement.querySelector('.avatar-base')?.classList.add('morphed');renderAvatarMorphCanvases()};img.onerror=()=>{};img.src=canvas.dataset.src}},true);

root.addEventListener('submit',event=>{if(event.target.id==='onboarding-form'){event.preventDefault();saveOnboarding(event.target).catch(handleError)}});
